#include "gesummv.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// layouts (row-major: inner dimension is the first one composed)
constexpr auto mat_layout = j_vec ^ i_vec; // i x j
constexpr auto x_layout   = j_vec;         // length N, indexed by 'j'
constexpr auto y_layout   = i_vec;         // length N, indexed by 'i'

// initialization function
void init_array(num_t &alpha, num_t &beta, auto A, auto B, auto x) {
	using namespace noarr;

	// matrices are N x N
	auto n = A | get_length<'i'>();

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Use a reciprocal to replace divisions by a cheaper multiply
	const num_t inv_n = num_t(1.0) / num_t(n);

	// Original C:
	// for (i = 0; i < n; i++) {
	//   x[i] = (DATA_TYPE)( i % n) / n;
	//   for (j = 0; j < n; j++) {
	//     A[i][j] = (DATA_TYPE)((i*j+1) % n) / n;
	//     B[i][j] = (DATA_TYPE)((i*j+2) % n) / n;
	//   }
	// }

	traverser(A, B, x).template for_dims<'i'>([=](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // contains index in 'i'
		auto i  = get_index<'i'>(si);

		// x[i]  — x is indexed by 'j', so we use j = i
		// i is in [0, n), so (i % n) == i; we can safely drop the modulus
		x[idx<'j'>(i)] = num_t(i) * inv_n;

		// A[i][j], B[i][j]
		inner.for_each([=](auto s) {
			auto j = get_index<'j'>(s);

			A[s] = num_t((i * j + 1) % n) * inv_n;
			B[s] = num_t((i * j + 2) % n) * inv_n;
		});
	});
}

// computation kernel
//
// Optimization vs original:
// - Keep traversal order (i outer, j inner) to match row-major layout.
// - Accumulate tmp[i] and y[i] in scalar locals tmp_i / y_i and write
//   them back once per row. This avoids repeated loads/stores of tmp[i]
//   and y[i] inside the inner j-loop, reducing memory traffic and giving
//   the compiler a clearer, vectorizable reduction pattern.
// - Reuse x[j] within the inner loop body via x[s], where s has both
//   'i' and 'j'; x ignores the extra 'i' index.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
	//   y[i] = 0.0;
	//   for (j = 0; j < _PB_N; j++) {
	//     tmp[i] = A[i][j] * x[j] + tmp[i];
	//     y[i]   = B[i][j] * x[j] + y[i];
	//   }
	//   y[i] = alpha * tmp[i] + beta * y[i];
	// }

	#pragma scop
	traverser(A, B, x).template for_dims<'i'>([=, &tmp, &y](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state with fixed 'i'

		// Local accumulators for this row i
		num_t tmp_i = (num_t)0.0;
		num_t y_i   = (num_t)0.0;

		// for j: accumulate tmp_i and y_i
		inner.for_each([&](auto s) {
			// s has both 'i' and 'j'
			// x is 1D in 'j', the extra 'i' in s is ignored by x[]
			const num_t xj = x[s];

			tmp_i += A[s] * xj;
			y_i   += B[s] * xj;
		});

		// Write back the accumulated results:
		// tmp[i] = sum_j A[i][j] * x[j];
		// y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j];
		tmp[si] = tmp_i;
		y[si]   = alpha * tmp_i + beta * y_i;
	});
	#pragma endscop
}

